  "check_code": "import datetime
import sqlite3
from pathlib import Path


DATASET_ID = "DS-PDS-CIV-2024-017"


def _db(ws):
    return Path(ws).parent / "system" / "mininglamp_data_catalog" / "state.db"


def _row(ws, sql, args=()):
    con = sqlite3.connect(_db(ws))
    con.row_factory = sqlite3.Row
    try:
        return con.execute(sql, args).fetchone()
    finally:
        con.close()


def check_catalog_controls(ws):
    row = _row(ws, "SELECT approved_scenario_id, approved_sharing_mode, authorization_end_date, sharing_scope, usage_condition FROM catalog_datasets WHERE dataset_id=?", (DATASET_ID,))
    actual = tuple(row) if row else None
    usage = (row[4] or "") if row else ""
    controls = {
        "dedicated_service_account": any(p in usage for p in ("专用服务账号", "专用账号", "pds_zjj_bzzf_lh_service", "PDS-ZJJ-BZF-PRD-02")),
        "purpose_limited": any(p in usage for p in ("仅服务于", "仅限", "仅用于")) and "保障性住房资格联审" in usage,
        "authorized_result_only": "仅返回" in usage and "最终授权边界内" in usage and "核验结果" in usage,
        "no_batch_export": any(p in usage for p in ("禁止批量导出", "不得批量导出", "不开放批量导出")),
        "no_third_party_transfer": any(p in usage for p in ("禁止向第三方转提供", "不得向第三方提供", "禁止第三方提供")),
    }
    fixed = actual[:4] == ("SCN-PDS-HOUSING-JOINT-REVIEW-001", "api", "2026-09-30", "申请人及共同申请家庭成员") if actual else False
    ok = fixed and all(controls.values())
    return {"score": int(ok), "detail": f"fixed={fixed}; controls={controls!r}; actual_usage={usage!r}"}


def check_catalog_version(ws):
    row = _row(ws, "SELECT updated_at FROM catalog_datasets WHERE dataset_id=?", (DATASET_ID,))
    value = row[0] if row else None
    today = datetime.date.today()
    try:
        value_date = datetime.date.fromisoformat(value) if value else None
    except (TypeError, ValueError):
        value_date = None
    start = datetime.date(2026, 8, 14)
    ok = value_date is not None and start <= value_date <= today
    return {"score": int(ok), "detail": f"updated_at={value!r}; accepted execution-date window=[{start.isoformat()}, {today.isoformat()}]"}


def check_untouched_records(ws):
    current = _db(ws)
    con = sqlite3.connect(current)
    try:
        counts = {
            table: con.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
            for table in ("catalog_datasets", "catalog_fields", "legal_basis_rules")
        }
        if counts != {"catalog_datasets": 49, "catalog_fields": 188, "legal_basis_rules": 41}:
            return {"score": 0, "detail": f"unexpected row counts: {counts!r}"}
        dataset = con.execute(
            "SELECT provider_org_id, provider_org_name, dataset_name, sharing_attribute, update_frequency, catalog_owner_org_id, lifecycle_status, created_at FROM catalog_datasets WHERE dataset_id=?",
            (DATASET_ID,),
        ).fetchone()
        expected_dataset = ("ORG-PDS-CIVIL-001", "平顶山市民政局", "社会救助与婚姻登记核验数据集", "conditional", "T+1", "ORG-PDS-BIGDATA-001", "published", "2024-02-18")
        if dataset != expected_dataset:
            return {"score": 0, "detail": "immutable target dataset metadata changed"}
        field_rows = con.execute(
            "SELECT field_id, standard_field_code, field_name, data_format, classification_level, sharing_mode, legal_basis_code, sharing_condition, retention_requirement_days, lifecycle_status, created_at FROM catalog_fields WHERE dataset_id=? ORDER BY field_id",
            (DATASET_ID,),
        ).fetchall()
        if len(field_rows) != 6 or any(row[5] not in {"api", "not_shared"} for row in field_rows):
            return {"score": 0, "detail": "target field structure or sharing mode changed"}
    finally:
        con.close()
    return {"score": 1, "detail": "row counts and immutable target metadata remain intact"}
